def check_overlap(placement1, placement2):
    return any(pc in placement1['cells'] for pc in placement2['cells'])

def backtrack(idx, current_placements, colors_list):
    if idx == len(colors_list):
        return current_placements.copy()

    color = colors_list[idx]
    for i, placement in enumerate(placements_per_object[color]):
        new_placements = current_placements.copy()
        new_placements[color] = placement

