        conflict = False
        for prev_color, prev_p in new_placements.items():
            if prev_color != color and check_overlap(prev_p, placement):
                conflict = True
                break

        if not conflict:
            result = backtrack(idx + 1, new_placements, colors_list)
            if result:
                return result

    return None

