# Update solver to maximize lowest row used
def backtrack_bfs(idx, current_placements, colors_list):
    """Breadth-first search to find placement maximizing lowest row"""
    queue = [(0, {}, set())]  # (idx, placements, all_cells_set)
    visited = set()

    while queue:
        idx, placements, all_cells = queue.pop(0)

        state_key = tuple(sorted(placements.items()))
        if state_key in visited:
            continue
        visited.add(state_key)

        if idx == len(colors_list):
            # Found a complete placement, return it
            return placements.copy()

        color = colors_list[idx]
        for i, placement in enumerate(placements_per_object[color]):
            new_placements = dict(placements)
            new_placements[color] = placement
            new_cells = all_cells | set(tuple(c) for c in placement['cells'])

            # Check overlap
            conflict = False
            for prev_color, prev_p in new_placements.items():
                if prev_color != color:
                    for pc in placement['cells']:
                        if pc in prev_p['cells']:
                            conflict = True
                            break
                    if conflict:
                        break

            if not conflict:
                queue.append((idx + 1, new_placements, new_cells))

    return None

# BFS is too slow, let's use DFS with best-first ordering
best_solution = None
best_score = -float('inf')

def dfs_with_order(idx, current_placements, current_all_cells, order_idx):
    global best_solution, best_score

    if order_idx >= len(colors_list):
        # Calculate score: sum of max_row for each object (want them low)
        score = sum(p['top_row'] + p['height'] for p in current_placements.values())
        if score > best_score:
            best_score = score
            best_solution = dict(current_placements)
        return

    color = colors_list[order_idx]
    # Sort placements by top_row descending (try lower positions first)
    sorted_placements = sorted(placements_per_object[color], 
                              key=lambda p: (p['top_row'], p['top_col']), 
                              reverse=True)

    for placement in sorted_placements:
        # Check overlap
        conflict = False
        for prev_color, prev_p in current_placements.items():
            for pc in placement['cells']:
                if pc in prev_p['cells']:
                    conflict = True
                    break
            if conflict:
                break

        if not conflict:
            current_placements[color] = placement
            new_all_cells = current_all_cells | set(tuple(c) for c in placement['cells'])
            dfs_with_order(idx, current_placements, new_all_cells, order_idx + 1)
            del current_placements[color]

